import { AssetType, defineAssets } from '@iwsdk/core';

const publicAssetUrl = (filePath: string): string =>
  `${import.meta.env.BASE_URL}${filePath.replace(/^\/+/u, '')}`;

export default defineAssets({
  'menu-panel': {
    url: publicAssetUrl('ui/menu.uikitml'),
    type: AssetType.UIKitML,
    name: 'Menu Panel',
  },
  'hud-panel': {
    url: publicAssetUrl('ui/hud.uikitml'),
    type: AssetType.UIKitML,
    name: 'HUD Panel',
  },
  'wave-complete-panel': {
    url: publicAssetUrl('ui/wave-complete.uikitml'),
    type: AssetType.UIKitML,
    name: 'Wave Complete Panel',
  },
  'game-over-panel': {
    url: publicAssetUrl('ui/game-over.uikitml'),
    type: AssetType.UIKitML,
    name: 'Game Over Panel',
  },
  'settings-panel': {
    url: publicAssetUrl('ui/settings.uikitml'),
    type: AssetType.UIKitML,
    name: 'Settings Panel',
  },
  'tutorial-panel': {
    url: publicAssetUrl('ui/tutorial.uikitml'),
    type: AssetType.UIKitML,
    name: 'Tutorial Panel',
  },
  'compass-panel': {
    url: publicAssetUrl('ui/compass.uikitml'),
    type: AssetType.UIKitML,
    name: 'Compass Panel',
  },
});

import { World } from '@iwsdk/core';
import projectOptions from 'virtual:iwsdk-project';
import { EnvironmentSystem } from './environment-system.js';
import { LighthouseSystem } from './lighthouse-system.js';
import { ShipSystem } from './ship-system.js';
import { AudioSystem } from './audio-system.js';
import { GameSystem } from './game-system.js';

World.create(
  document.getElementById('scene-container') as HTMLDivElement,
  projectOptions,
).then((world) => {
  // Register in dependency order
  world.registerSystem(AudioSystem);
  world.registerSystem(EnvironmentSystem);
  world.registerSystem(LighthouseSystem);
  world.registerSystem(ShipSystem);
  world.registerSystem(GameSystem);
});

import { iwsdkDev } from '@iwsdk/vite-plugin-dev';
import { defineConfig } from 'vite';

export default defineConfig({
  plugins: [iwsdkDev()],
  server: { host: '0.0.0.0', port: 8081, open: false },
  build: {
    outDir: 'dist',
    sourcemap: process.env.NODE_ENV !== 'production',
    target: 'esnext',
    rollupOptions: { input: './index.html' },
  },
  esbuild: { target: 'esnext' },
  optimizeDeps: {
    exclude: ['@babylonjs/havok'],
    esbuildOptions: { target: 'esnext' },
  },
  publicDir: 'public',
  base: './',
});

import { createComponent, Types, defineComponents } from '@iwsdk/core';

export const Ship = createComponent('Ship', {
  speed: { type: Types.Float32, default: 0.8 },
  headingAngle: { type: Types.Float32, default: 0 },
  isLit: { type: Types.Boolean, default: false },
  litTimer: { type: Types.Float32, default: 0 },
  docked: { type: Types.Boolean, default: false },
  sinking: { type: Types.Boolean, default: false },
  sinkProgress: { type: Types.Float32, default: 0 },
  spawnAngle: { type: Types.Float32, default: 0 },
});

export const Rock = createComponent('Rock', {
  damageRadius: { type: Types.Float32, default: 1.5 },
});

export const Harbor = createComponent('Harbor', {
  dockRadius: { type: Types.Float32, default: 3.0 },
});

export const LighthouseBeam = createComponent('LighthouseBeam', {
  range: { type: Types.Float32, default: 60 },
  coneAngle: { type: Types.Float32, default: 0.18 },
  active: { type: Types.Boolean, default: true },
});

export const StarField = createComponent('StarField', {
  count: { type: Types.Int32, default: 400 },
});

export const OceanTile = createComponent('OceanTile', {
  waveSpeed: { type: Types.Float32, default: 1.0 },
});

export default defineComponents([
  Ship,
  Rock,
  Harbor,
  LighthouseBeam,
  StarField,
  OceanTile,
]);

import { createSystem, UIKitMLAsset } from '@iwsdk/core';
import { ShipSystem } from './ship-system.js';
import { LighthouseSystem } from './lighthouse-system.js';
import { AudioSystem } from './audio-system.js';
import { EnvironmentSystem } from './environment-system.js';

type GameState = 'menu' | 'tutorial' | 'settings' | 'playing' | 'wave-complete' | 'game-over';

interface WaveConfig {
  shipCount: number;
  spawnInterval: number;
  shipSpeed: number;
  fogDensity: number;
  stormChance: number;
}

export class GameSystem extends createSystem({}) {
  private state: GameState = 'menu';
  private wave = 0;
  private score = 0;
  private lives = 3;
  private highScore = 0;
  private bestWave = 0;
  private totalShipsSaved = 0;
  private waveShipsSaved = 0;
  private waveShipsLost = 0;
  private waveShipTotal = 0;
  private fogHornTimer = 0;

  private shipSystem!: ShipSystem;
  private lighthouseSystem!: LighthouseSystem;
  private audioSystem!: AudioSystem;
  private envSystem!: EnvironmentSystem;

  // Panels
  private menuPanel: UIKitMLAsset | undefined = undefined;
  private hudPanel: UIKitMLAsset | undefined = undefined;
  private waveCompletePanel: UIKitMLAsset | undefined = undefined;
  private gameOverPanel: UIKitMLAsset | undefined = undefined;
  private settingsPanel: UIKitMLAsset | undefined = undefined;
  private tutorialPanel: UIKitMLAsset | undefined = undefined;
  private compassPanel: UIKitMLAsset | undefined = undefined;

  init() {
    this.shipSystem = this.world.getSystem(ShipSystem)!;
    this.lighthouseSystem = this.world.getSystem(LighthouseSystem)!;
    this.audioSystem = this.world.getSystem(AudioSystem)!;
    this.envSystem = this.world.getSystem(EnvironmentSystem)!;

    // Load saved scores
    this.highScore = parseInt(localStorage.getItem('neon-lighthouse-high-score') || '0', 10);
    this.bestWave = parseInt(localStorage.getItem('neon-lighthouse-best-wave') || '0', 10);

    // Get panels
    this.menuPanel = this.world.getSceneObject<UIKitMLAsset>('menu-panel-node');
    this.hudPanel = this.world.getSceneObject<UIKitMLAsset>('hud-panel-node');
    this.waveCompletePanel = this.world.getSceneObject<UIKitMLAsset>('wave-complete-panel-node');
    this.gameOverPanel = this.world.getSceneObject<UIKitMLAsset>('game-over-panel-node');
    this.settingsPanel = this.world.getSceneObject<UIKitMLAsset>('settings-panel-node');
    this.tutorialPanel = this.world.getSceneObject<UIKitMLAsset>('tutorial-panel-node');
    this.compassPanel = this.world.getSceneObject<UIKitMLAsset>('compass-panel-node');

    this.setupPanelButtons();
    this.showState('menu');
  }

  private setupPanelButtons() {
    // Menu buttons
    this.menuPanel?.getElementById('btn-play')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.startGame();
    });
    this.menuPanel?.getElementById('btn-tutorial')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.showState('tutorial');
    });
    this.menuPanel?.getElementById('btn-settings')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.showState('settings');
    });

    // Tutorial
    this.tutorialPanel?.getElementById('btn-got-it')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.showState('menu');
    });

    // Settings
    this.settingsPanel?.getElementById('btn-sensitivity')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
    });
    this.settingsPanel?.getElementById('btn-volume')?.addEventListener('click', () => {
      this.audioSystem.toggleVolume();
      this.audioSystem.playUIClick();
      this.settingsPanel?.getElementById('volume-val')?.setProperties({
        text: this.audioSystem.isVolumeOn() ? 'ON' : 'OFF',
      });
    });
    this.settingsPanel?.getElementById('btn-back')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.showState('menu');
    });

    // Wave complete
    this.waveCompletePanel?.getElementById('btn-next-wave')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.startWave();
    });

    // Game over
    this.gameOverPanel?.getElementById('btn-play-again')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.startGame();
    });
    this.gameOverPanel?.getElementById('btn-main-menu')?.addEventListener('click', () => {
      this.audioSystem.playUIClick();
      this.showState('menu');
    });
  }

  private showState(newState: GameState) {
    this.state = newState;
    const panels = [
      { panel: this.menuPanel, show: newState === 'menu' },
      { panel: this.hudPanel, show: newState === 'playing' },
      { panel: this.waveCompletePanel, show: newState === 'wave-complete' },
      { panel: this.gameOverPanel, show: newState === 'game-over' },
      { panel: this.settingsPanel, show: newState === 'settings' },
      { panel: this.tutorialPanel, show: newState === 'tutorial' },
      { panel: this.compassPanel, show: newState === 'playing' },
    ];
    for (const { panel, show } of panels) {
      if (panel) panel.visible = show;
    }
  }

  private startGame() {
    this.score = 0;
    this.lives = 3;
    this.wave = 0;
    this.totalShipsSaved = 0;
    this.shipSystem.clearAllShips();
    this.envSystem.setFogDensity(0.012);

    // Update menu high scores
    this.menuPanel?.getElementById('high-score')?.setProperties({ text: String(this.highScore) });
    this.menuPanel?.getElementById('best-wave')?.setProperties({ text: String(this.bestWave) });

    this.startWave();
  }

  private startWave() {
    this.wave++;
    this.waveShipsSaved = 0;
    this.waveShipsLost = 0;
    this.shipSystem.clearAllShips();

    const config = this.getWaveConfig(this.wave);
    this.waveShipTotal = config.shipCount;
    this.shipSystem.shipsToSpawn = config.shipCount;
    this.shipSystem.spawnInterval = config.spawnInterval;
    this.shipSystem.baseSpeed = config.shipSpeed;
    this.shipSystem.spawnTimer = 0.5;

    this.envSystem.setFogDensity(config.fogDensity);

    if (config.stormChance > Math.random()) {
      this.audioSystem.playStormWind();
    }

    this.lighthouseSystem.setBeamActive(true);
    this.showState('playing');
    this.updateHUD();
  }

  private getWaveConfig(wave: number): WaveConfig {
    return {
      shipCount: 3 + wave * 2,
      spawnInterval: Math.max(1.5, 4 - wave * 0.3),
      shipSpeed: 0.6 + wave * 0.08,
      fogDensity: 0.012 + wave * 0.002,
      stormChance: Math.min(wave * 0.1, 0.7),
    };
  }

  private updateHUD() {
    this.hudPanel?.getElementById('score')?.setProperties({ text: String(this.score) });
    this.hudPanel?.getElementById('lives')?.setProperties({ text: String(this.lives) });
    this.hudPanel?.getElementById('wave')?.setProperties({ text: String(this.wave) });
    const activeShips = this.shipSystem.getActiveShipCount() + this.shipSystem.shipsToSpawn;
    this.hudPanel?.getElementById('ships-remaining')?.setProperties({ text: String(activeShips) });
    this.hudPanel?.getElementById('beam-power')?.setProperties({
      text: this.lighthouseSystem.isBeamActive() ? 'ON' : 'OFF',
    });
  }

  private updateCompass() {
    const ships = this.shipSystem.getAllShips();
    const dirs = ['n', 'ne', 'e', 'se', 's', 'sw', 'w', 'nw'];
    const dirAngles = [
      Math.PI, 3 * Math.PI / 4, Math.PI / 2, Math.PI / 4,
      0, -Math.PI / 4, -Math.PI / 2, -3 * Math.PI / 4,
    ];
    const activeInDir = new Array(8).fill(false);

    for (const ship of ships) {
      if (ship.docked || ship.sinking) continue;
      const pos = ship.entity.object3D!.position;
      const angle = Math.atan2(pos.x, pos.z);
      // Find closest direction
      let bestIdx = 0;
      let bestDist = Infinity;
      for (let d = 0; d < 8; d++) {
        let diff = Math.abs(angle - dirAngles[d]);
        if (diff > Math.PI) diff = Math.PI * 2 - diff;
        if (diff < bestDist) {
          bestDist = diff;
          bestIdx = d;
        }
      }
      activeInDir[bestIdx] = true;
    }

    for (let d = 0; d < 8; d++) {
      const dirEl = this.compassPanel?.getElementById(`dir-${dirs[d]}`);
      const dotEl = this.compassPanel?.getElementById(`dot-${dirs[d]}`);
      if (activeInDir[d]) {
        dirEl?.setProperties({ color: '#ff6644' });
        dotEl?.setProperties({ backgroundColor: '#ff6644' });
      } else {
        dirEl?.setProperties({ color: 'rgba(180, 200, 220, 0.5)' });
        dotEl?.setProperties({ backgroundColor: 'rgba(100, 120, 140, 0.3)' });
      }
    }
  }

  private checkWaveComplete() {
    const ships = this.shipSystem.getAllShips();
    const allSpawned = this.shipSystem.shipsToSpawn <= 0;
    if (!allSpawned) return;

    let anyActive = false;
    let docked = 0;
    let sunk = 0;
    for (const ship of ships) {
      if (ship.docked) {
        docked++;
      } else if (ship.sinking) {
        sunk++;
      } else {
        anyActive = true;
      }
    }

    if (anyActive) return;

    // Wave done
    this.waveShipsSaved = docked;
    this.waveShipsLost = this.waveShipTotal - docked;

    // Score
    const savePoints = docked * 100;
    const perfectBonus = this.waveShipsLost === 0 ? 500 : 0;
    const waveScore = savePoints + perfectBonus;
    this.score += waveScore;
    this.totalShipsSaved += docked;

    // Lose lives for lost ships
    this.lives -= this.waveShipsLost;

    if (this.lives <= 0) {
      this.gameOver();
      return;
    }

    // Show wave complete
    this.audioSystem.playWaveComplete();
    const stars = this.waveShipsLost === 0 ? 3 : this.waveShipsLost <= 1 ? 2 : 1;
    const starStr = Array(stars).fill('\u2605').join(' ') +
      (stars < 3 ? ' ' + Array(3 - stars).fill('\u2606').join(' ') : '');

    this.waveCompletePanel?.getElementById('wave-num')?.setProperties({ text: `Wave ${this.wave}` });
    this.waveCompletePanel?.getElementById('ships-saved')?.setProperties({ text: String(docked) });
    this.waveCompletePanel?.getElementById('ships-lost')?.setProperties({ text: String(this.waveShipsLost) });
    this.waveCompletePanel?.getElementById('bonus')?.setProperties({ text: `+${perfectBonus}` });
    this.waveCompletePanel?.getElementById('stars')?.setProperties({ text: starStr });

    this.showState('wave-complete');
  }

  private gameOver() {
    this.audioSystem.playGameOver();

    // Update high scores
    let isNewHigh = false;
    if (this.score > this.highScore) {
      this.highScore = this.score;
      localStorage.setItem('neon-lighthouse-high-score', String(this.highScore));
      isNewHigh = true;
    }
    if (this.wave > this.bestWave) {
      this.bestWave = this.wave;
      localStorage.setItem('neon-lighthouse-best-wave', String(this.bestWave));
    }

    this.gameOverPanel?.getElementById('final-score')?.setProperties({ text: String(this.score) });
    this.gameOverPanel?.getElementById('waves-survived')?.setProperties({ text: String(this.wave) });
    this.gameOverPanel?.getElementById('total-ships-saved')?.setProperties({ text: String(this.totalShipsSaved) });
    this.gameOverPanel?.getElementById('new-high-label')?.setProperties({
      text: isNewHigh ? 'NEW HIGH SCORE!' : ' ',
    });

    this.menuPanel?.getElementById('high-score')?.setProperties({ text: String(this.highScore) });
    this.menuPanel?.getElementById('best-wave')?.setProperties({ text: String(this.bestWave) });

    this.shipSystem.clearAllShips();
    this.showState('game-over');
  }

  update(delta: number, _time: number) {
    if (this.state === 'playing') {
      this.updateHUD();
      this.updateCompass();
      this.checkWaveComplete();

      // Periodic foghorn
      this.fogHornTimer -= delta;
      if (this.fogHornTimer <= 0) {
        this.audioSystem.playFoghorn();
        this.fogHornTimer = 15 + Math.random() * 10;
      }
    }
  }
}

import {
  createSystem,
  World,
  Vector3,
  Mesh,
  PlaneGeometry,
  ShaderMaterial,
  CylinderGeometry,
  MeshStandardMaterial,
  SphereGeometry,
  ConeGeometry,
  BoxGeometry,
  PointLight,
  AmbientLight,
  FogExp2,
  BufferGeometry,
  BufferAttribute,
  Points,
  PointsMaterial,
  MeshBasicMaterial,
  Color,
  DoubleSide,
  AdditiveBlending,
  Group,
} from '@iwsdk/core';

const OCEAN_SIZE = 200;
const OCEAN_SEGMENTS = 80;
const LIGHTHOUSE_HEIGHT = 10;
const HARBOR_POS = new Vector3(8, 0, -5);
const NUM_ROCKS = 12;
const STAR_COUNT = 600;

export class EnvironmentSystem extends createSystem({}) {
  private oceanMesh!: Mesh;
  private oceanGeo!: PlaneGeometry;
  private posAttr!: BufferAttribute;
  private origY!: Float32Array;
  private fogDensity = 0.012;
  private targetFogDensity = 0.012;
  private harborLights: PointLight[] = [];
  private starPoints!: Points;
  private lighthouseGroup!: Group;
  private lanternLight!: PointLight;

  // Exposed for other systems
  public rockPositions: Vector3[] = [];
  public harborPosition = HARBOR_POS.clone();

  init() {
    this.buildOcean();
    this.buildLighthouse();
    this.buildHarbor();
    this.buildRocks();
    this.buildStarfield();
    this.buildLighting();
  }

  private buildOcean() {
    const geo = new PlaneGeometry(OCEAN_SIZE, OCEAN_SIZE, OCEAN_SEGMENTS, OCEAN_SEGMENTS);
    geo.rotateX(-Math.PI / 2);
    const mat = new ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uDeepColor: { value: new Color(0x001428) },
        uShallowColor: { value: new Color(0x003344) },
        uFoamColor: { value: new Color(0x00ffcc) },
      },
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying float vElevation;
        void main() {
          vUv = uv;
          vec3 pos = position;
          float wave1 = sin(pos.x * 0.15 + uTime * 0.8) * 0.3;
          float wave2 = sin(pos.z * 0.12 + uTime * 0.6) * 0.25;
          float wave3 = sin((pos.x + pos.z) * 0.08 + uTime * 1.1) * 0.15;
          pos.y += wave1 + wave2 + wave3;
          vElevation = wave1 + wave2 + wave3;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform vec3 uDeepColor;
        uniform vec3 uShallowColor;
        uniform vec3 uFoamColor;
        varying vec2 vUv;
        varying float vElevation;
        void main() {
          float depth = smoothstep(-0.4, 0.5, vElevation);
          vec3 col = mix(uDeepColor, uShallowColor, depth);
          float foam = smoothstep(0.35, 0.5, vElevation);
          col = mix(col, uFoamColor, foam * 0.15);
          gl_FragColor = vec4(col, 0.92);
        }
      `,
      transparent: true,
      side: DoubleSide,
    });
    this.oceanMesh = new Mesh(geo, mat);
    this.oceanGeo = geo;
    this.posAttr = geo.getAttribute('position') as BufferAttribute;
    this.origY = new Float32Array(this.posAttr.count);
    for (let i = 0; i < this.posAttr.count; i++) {
      this.origY[i] = this.posAttr.getY(i);
    }
    const oceanEntity = this.world.createTransformEntity(this.oceanMesh);
    oceanEntity.object3D!.position.set(0, -0.2, 0);

    // Set scene fog
    this.world.scene.fog = new FogExp2(0x010818, this.fogDensity);
  }

  private buildLighthouse() {
    this.lighthouseGroup = new Group();

    // Tower base — wide cylinder
    const baseMat = new MeshStandardMaterial({ color: 0x334455, roughness: 0.8 });
    const baseGeo = new CylinderGeometry(2.5, 3.0, 2, 12);
    const baseMesh = new Mesh(baseGeo, baseMat);
    baseMesh.position.set(0, 1, 0);
    this.lighthouseGroup.add(baseMesh);

    // Tower body — tall tapered cylinder
    const towerMat = new MeshStandardMaterial({ color: 0xcccccc, roughness: 0.6 });
    const towerGeo = new CylinderGeometry(1.5, 2.2, LIGHTHOUSE_HEIGHT - 2, 12);
    const towerMesh = new Mesh(towerGeo, towerMat);
    towerMesh.position.set(0, (LIGHTHOUSE_HEIGHT - 2) / 2 + 2, 0);
    this.lighthouseGroup.add(towerMesh);

    // Red stripe bands
    const stripeMat = new MeshStandardMaterial({ color: 0xcc2222, roughness: 0.5 });
    for (let i = 0; i < 3; i++) {
      const stripeGeo = new CylinderGeometry(
        1.5 + (2 - i) * 0.15,
        1.5 + (2 - i) * 0.2,
        0.6,
        12,
      );
      const stripe = new Mesh(stripeGeo, stripeMat);
      stripe.position.set(0, 3 + i * 2.5, 0);
      this.lighthouseGroup.add(stripe);
    }

    // Lantern room — glass housing
    const lanternMat = new MeshStandardMaterial({
      color: 0xffcc44,
      emissive: 0xffaa22,
      emissiveIntensity: 0.5,
      transparent: true,
      opacity: 0.7,
    });
    const lanternGeo = new CylinderGeometry(1.8, 1.8, 1.5, 8);
    const lanternMesh = new Mesh(lanternGeo, lanternMat);
    lanternMesh.position.set(0, LIGHTHOUSE_HEIGHT + 0.75, 0);
    this.lighthouseGroup.add(lanternMesh);

    // Lantern cap
    const capMat = new MeshStandardMaterial({ color: 0x222222 });
    const capGeo = new ConeGeometry(2.0, 1.5, 8);
    const capMesh = new Mesh(capGeo, capMat);
    capMesh.position.set(0, LIGHTHOUSE_HEIGHT + 2.25, 0);
    this.lighthouseGroup.add(capMesh);

    // Lantern light
    this.lanternLight = new PointLight(0xffaa22, 3, 30);
    this.lanternLight.position.set(0, LIGHTHOUSE_HEIGHT + 0.75, 0);
    this.lighthouseGroup.add(this.lanternLight);

    // Railing at top
    const railMat = new MeshStandardMaterial({ color: 0x444444 });
    for (let i = 0; i < 8; i++) {
      const angle = (i / 8) * Math.PI * 2;
      const railGeo = new CylinderGeometry(0.05, 0.05, 1.2, 4);
      const railPost = new Mesh(railGeo, railMat);
      railPost.position.set(
        Math.cos(angle) * 2.0,
        LIGHTHOUSE_HEIGHT + 0.1,
        Math.sin(angle) * 2.0,
      );
      this.lighthouseGroup.add(railPost);
    }

    const entity = this.world.createTransformEntity(this.lighthouseGroup);
    entity.object3D!.position.set(0, 0, 0);
  }

  private buildHarbor() {
    const harborGroup = new Group();

    // Main pier
    const pierMat = new MeshStandardMaterial({ color: 0x664422, roughness: 0.9 });
    const pierGeo = new BoxGeometry(8, 0.5, 3);
    const pierMesh = new Mesh(pierGeo, pierMat);
    pierMesh.position.set(0, 0.3, 0);
    harborGroup.add(pierMesh);

    // Pier supports
    const supportMat = new MeshStandardMaterial({ color: 0x553311 });
    for (let x = -3; x <= 3; x += 2) {
      const supportGeo = new CylinderGeometry(0.15, 0.15, 2, 6);
      const support = new Mesh(supportGeo, supportMat);
      support.position.set(x, -0.7, 0);
      harborGroup.add(support);
    }

    // Harbor guide lights
    const lightColors = [0x00ff44, 0xff2222, 0x00ff44];
    for (let i = 0; i < 3; i++) {
      const lightGeo = new SphereGeometry(0.15, 8, 8);
      const lightMat = new MeshBasicMaterial({
        color: lightColors[i],
      });
      const lightMesh = new Mesh(lightGeo, lightMat);
      lightMesh.position.set(-3 + i * 3, 1, 1.5);
      harborGroup.add(lightMesh);

      const pl = new PointLight(lightColors[i], 1, 8);
      pl.position.copy(lightMesh.position);
      harborGroup.add(pl);
      this.harborLights.push(pl);
    }

    const entity = this.world.createTransformEntity(harborGroup);
    entity.object3D!.position.copy(HARBOR_POS);
  }

  private buildRocks() {
    const rockMat = new MeshStandardMaterial({
      color: 0x2a2a2a,
      roughness: 1.0,
    });

    const rockPositions = [
      new Vector3(-15, -0.5, -20),
      new Vector3(-25, -0.3, -10),
      new Vector3(20, -0.4, -25),
      new Vector3(-10, -0.6, -35),
      new Vector3(30, -0.3, -15),
      new Vector3(-30, -0.4, -30),
      new Vector3(15, -0.5, -40),
      new Vector3(-20, -0.3, -45),
      new Vector3(25, -0.5, -35),
      new Vector3(-35, -0.6, -20),
      new Vector3(35, -0.4, -40),
      new Vector3(5, -0.3, -50),
    ];

    for (const pos of rockPositions) {
      const rockGroup = new Group();
      const mainSize = 1 + Math.random() * 1.5;
      const mainGeo = new SphereGeometry(mainSize, 6, 5);
      const mainRock = new Mesh(mainGeo, rockMat);
      mainRock.scale.set(1, 0.5 + Math.random() * 0.3, 1);
      rockGroup.add(mainRock);

      // Secondary smaller rocks
      for (let j = 0; j < 2; j++) {
        const smallSize = 0.5 + Math.random() * 0.8;
        const smallGeo = new SphereGeometry(smallSize, 5, 4);
        const smallRock = new Mesh(smallGeo, rockMat);
        smallRock.position.set(
          (Math.random() - 0.5) * 2,
          0,
          (Math.random() - 0.5) * 2,
        );
        smallRock.scale.set(1, 0.4 + Math.random() * 0.3, 1);
        rockGroup.add(smallRock);
      }

      const entity = this.world.createTransformEntity(rockGroup);
      entity.object3D!.position.copy(pos);
      this.rockPositions.push(pos.clone());
    }
  }

  private buildStarfield() {
    const positions = new Float32Array(STAR_COUNT * 3);
    const sizes = new Float32Array(STAR_COUNT);
    for (let i = 0; i < STAR_COUNT; i++) {
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.random() * Math.PI * 0.4;
      const r = 150 + Math.random() * 50;
      positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
      positions[i * 3 + 1] = r * Math.cos(phi);
      positions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
      sizes[i] = 0.5 + Math.random() * 1.5;
    }
    const geo = new BufferGeometry();
    geo.setAttribute('position', new BufferAttribute(positions, 3));
    geo.setAttribute('size', new BufferAttribute(sizes, 1));
    const mat = new PointsMaterial({
      color: 0xffffff,
      size: 0.8,
      transparent: true,
      opacity: 0.8,
      blending: AdditiveBlending,
      depthWrite: false,
    });
    this.starPoints = new Points(geo, mat);
    this.world.createTransformEntity(this.starPoints);
  }

  private buildLighting() {
    const ambient = new AmbientLight(0x112244, 0.3);
    this.world.createTransformEntity(ambient);
  }

  setFogDensity(density: number) {
    this.targetFogDensity = density;
  }

  update(delta: number, time: number) {
    // Animate ocean shader
    const mat = this.oceanMesh.material as ShaderMaterial;
    mat.uniforms.uTime.value = time;

    // Animate fog
    if (this.world.scene.fog instanceof FogExp2) {
      const fog = this.world.scene.fog;
      fog.density += (this.targetFogDensity - fog.density) * delta * 2;
    }

    // Pulse harbor lights
    for (const light of this.harborLights) {
      light.intensity = 0.8 + Math.sin(time * 2) * 0.4;
    }

    // Pulse lantern
    this.lanternLight.intensity = 2.5 + Math.sin(time * 3) * 0.5;

    // Twinkle stars
    const starMat = this.starPoints.material as PointsMaterial;
    starMat.opacity = 0.6 + Math.sin(time * 0.5) * 0.2;
  }
}

import {
  createSystem,
  Vector3,
  Vector2,
  Mesh,
  ConeGeometry,
  MeshBasicMaterial,
  Raycaster,
  SpotLight,
  AdditiveBlending,
  Group,
  InputComponent,
} from '@iwsdk/core';

const BEAM_LENGTH = 60;
const BEAM_RADIUS = 4;
const BEAM_ORIGIN = new Vector3(0, 11, 0);

export class LighthouseSystem extends createSystem({}) {
  private beamGroup!: Group;
  private beamMesh!: Mesh;
  private spotLight!: SpotLight;
  private beamDirection = new Vector3(0, 0, -1);
  private beamActive = true;
  private aimTarget = new Vector3(0, 0, -30);
  private raycaster = new Raycaster();

  // Mouse aim for browser mode
  private mouseNDC = new Vector2(0, 0);
  private mouseDown = false;

  // Exposed for other systems to read beam direction
  public getBeamDirection(): Vector3 {
    return this.beamDirection.clone();
  }

  public getBeamOrigin(): Vector3 {
    return BEAM_ORIGIN.clone();
  }

  public isBeamActive(): boolean {
    return this.beamActive;
  }

  public getBeamConeAngle(): number {
    return 0.18;
  }

  init() {
    this.buildBeam();
    this.setupMouseControls();
  }

  private buildBeam() {
    this.beamGroup = new Group();

    // Volumetric beam cone
    const beamGeo = new ConeGeometry(BEAM_RADIUS, BEAM_LENGTH, 16, 1, true);
    beamGeo.translate(0, -BEAM_LENGTH / 2, 0);
    const beamMat = new MeshBasicMaterial({
      color: 0xffcc44,
      transparent: true,
      opacity: 0.08,
      blending: AdditiveBlending,
      depthWrite: false,
    });
    this.beamMesh = new Mesh(beamGeo, beamMat);
    this.beamGroup.add(this.beamMesh);

    // Spot light for actual illumination
    this.spotLight = new SpotLight(0xffcc44, 5, BEAM_LENGTH, 0.2, 0.5);
    this.spotLight.position.set(0, 0, 0);
    this.beamGroup.add(this.spotLight);
    this.beamGroup.add(this.spotLight.target);

    const entity = this.world.createTransformEntity(this.beamGroup);
    entity.object3D!.position.copy(BEAM_ORIGIN);
  }

  private setupMouseControls() {
    const canvas = this.world.renderer.domElement;
    canvas.addEventListener('mousemove', (e: MouseEvent) => {
      this.mouseNDC.set(
        (e.clientX / window.innerWidth) * 2 - 1,
        -(e.clientY / window.innerHeight) * 2 + 1,
      );
    });
    canvas.addEventListener('mousedown', () => {
      this.mouseDown = true;
    });
    canvas.addEventListener('mouseup', () => {
      this.mouseDown = false;
    });
    canvas.addEventListener('click', () => {
      this.beamActive = !this.beamActive;
    });
  }

  setBeamActive(active: boolean) {
    this.beamActive = active;
  }

  toggleBeam() {
    this.beamActive = !this.beamActive;
  }

  update(delta: number, time: number) {
    this.handleXRInput();
    this.handleBrowserInput();
    this.updateBeamVisuals(time);
  }

  private handleXRInput() {
    const rightPad = this.world.input.xr.gamepads.right;
    if (!rightPad) return;

    // Toggle beam with trigger
    if (rightPad.getButtonDown(InputComponent.Trigger)) {
      this.beamActive = !this.beamActive;
    }

    // Use ray space for beam direction
    const raySpace = this.world.player.raySpaces.right;
    if (raySpace) {
      const worldPos = new Vector3();
      const worldDir = new Vector3(0, 0, -1);
      raySpace.getWorldPosition(worldPos);
      raySpace.getWorldDirection(worldDir);

      // Aim beam in ray direction projected from lighthouse top
      this.beamDirection.copy(worldDir).normalize();
    }
  }

  private handleBrowserInput() {
    // In browser mode, use mouse position to aim beam
    if (this.world.input.xr.gamepads.right) return; // XR mode active

    // Project mouse into world to determine beam direction
    this.raycaster.setFromCamera(
      this.mouseNDC,
      this.world.camera,
    );

    // Intersect with ocean plane (y=0)
    const planeY = 0;
    const origin = this.raycaster.ray.origin;
    const direction = this.raycaster.ray.direction;
    if (direction.y !== 0) {
      const t = (planeY - origin.y) / direction.y;
      if (t > 0) {
        this.aimTarget.set(
          origin.x + direction.x * t,
          planeY,
          origin.z + direction.z * t,
        );
        this.beamDirection
          .copy(this.aimTarget)
          .sub(BEAM_ORIGIN)
          .normalize();
      }
    }
  }

  private updateBeamVisuals(time: number) {
    const mat = this.beamMesh.material as MeshBasicMaterial;

    if (this.beamActive) {
      mat.opacity = 0.06 + Math.sin(time * 4) * 0.02;
      this.spotLight.intensity = 4 + Math.sin(time * 3) * 1;

      // Orient beam group to point in beam direction
      const target = BEAM_ORIGIN.clone().add(
        this.beamDirection.clone().multiplyScalar(BEAM_LENGTH),
      );
      this.beamGroup.lookAt(target);
      this.beamGroup.rotateX(Math.PI / 2); // Cone points along -Y, need to fix

      // Move spotlight target
      this.spotLight.target.position
        .copy(this.beamDirection)
        .multiplyScalar(BEAM_LENGTH);
    } else {
      mat.opacity = 0;
      this.spotLight.intensity = 0;
    }
  }
}

import {
  createSystem,
  Vector3,
  Mesh,
  BoxGeometry,
  MeshStandardMaterial,
  CylinderGeometry,
  SphereGeometry,
  MeshBasicMaterial,
  PointLight,
  Group,
} from '@iwsdk/core';
import { Ship } from './components.js';
import { LighthouseSystem } from './lighthouse-system.js';
import { EnvironmentSystem } from './environment-system.js';
import { AudioSystem } from './audio-system.js';

interface ShipData {
  entity: ReturnType<typeof createSystem.prototype.world.createTransformEntity>;
  group: Group;
  speed: number;
  heading: number;
  isLit: boolean;
  litTimer: number;
  docked: boolean;
  sinking: boolean;
  sinkProgress: number;
  spawnAngle: number;
  portLight: PointLight;
  starboardLight: PointLight;
}

const HARBOR_POS = new Vector3(8, 0, -5);
const DOCK_RADIUS = 4;
const SPAWN_DISTANCE = 55;
const BEAM_HIT_RADIUS = 6;

export class ShipSystem extends createSystem({}) {
  private ships: ShipData[] = [];
  private lighthouseSystem!: LighthouseSystem;
  private envSystem!: EnvironmentSystem;
  private audioSystem!: AudioSystem;
  private tempVec = new Vector3();
  private tempVec2 = new Vector3();

  // Game state (managed by GameSystem)
  public shipsToSpawn = 0;
  public spawnTimer = 0;
  public spawnInterval = 3;
  public baseSpeed = 0.8;
  public waveShipCount = 0;

  init() {
    this.lighthouseSystem = this.world.getSystem(LighthouseSystem)!;
    this.envSystem = this.world.getSystem(EnvironmentSystem)!;
    this.audioSystem = this.world.getSystem(AudioSystem)!;
  }

  spawnShip(): ShipData {
    const group = new Group();

    // Hull
    const hullMat = new MeshStandardMaterial({ color: 0x334455, roughness: 0.7 });
    const hullGeo = new BoxGeometry(1.2, 0.5, 2.8);
    const hull = new Mesh(hullGeo, hullMat);
    hull.position.y = 0.1;
    group.add(hull);

    // Cabin
    const cabinMat = new MeshStandardMaterial({ color: 0x556677, roughness: 0.6 });
    const cabinGeo = new BoxGeometry(0.8, 0.6, 1.0);
    const cabin = new Mesh(cabinGeo, cabinMat);
    cabin.position.set(0, 0.6, -0.3);
    group.add(cabin);

    // Mast
    const mastMat = new MeshStandardMaterial({ color: 0x888888 });
    const mastGeo = new CylinderGeometry(0.04, 0.04, 1.5, 4);
    const mast = new Mesh(mastGeo, mastMat);
    mast.position.set(0, 1.1, 0.3);
    group.add(mast);

    // Navigation lights
    // Port (red, left)
    const portLightGeo = new SphereGeometry(0.08, 6, 6);
    const portLightMat = new MeshBasicMaterial({ color: 0xff2222 });
    const portLightMesh = new Mesh(portLightGeo, portLightMat);
    portLightMesh.position.set(-0.7, 0.5, 1.2);
    group.add(portLightMesh);
    const portLight = new PointLight(0xff2222, 0.8, 5);
    portLight.position.copy(portLightMesh.position);
    group.add(portLight);

    // Starboard (green, right)
    const starLightGeo = new SphereGeometry(0.08, 6, 6);
    const starLightMat = new MeshBasicMaterial({ color: 0x22ff22 });
    const starLightMesh = new Mesh(starLightGeo, starLightMat);
    starLightMesh.position.set(0.7, 0.5, 1.2);
    group.add(starLightMesh);
    const starboardLight = new PointLight(0x22ff22, 0.8, 5);
    starboardLight.position.copy(starLightMesh.position);
    group.add(starboardLight);

    // Random spawn angle from edge
    const spawnAngle = Math.random() * Math.PI * 2;
    const spawnX = Math.cos(spawnAngle) * SPAWN_DISTANCE;
    const spawnZ = Math.sin(spawnAngle) * SPAWN_DISTANCE;

    const entity = this.world.createTransformEntity(group);
    entity.object3D!.position.set(spawnX, 0, spawnZ);

    // Initial heading toward center area
    const headingToCenter = Math.atan2(-spawnZ, -spawnX);

    const shipData: ShipData = {
      entity,
      group,
      speed: this.baseSpeed + Math.random() * 0.3,
      heading: headingToCenter,
      isLit: false,
      litTimer: 0,
      docked: false,
      sinking: false,
      sinkProgress: 0,
      spawnAngle,
      portLight,
      starboardLight,
    };

    this.ships.push(shipData);
    this.audioSystem?.playShipBell();
    return shipData;
  }

  getActiveShipCount(): number {
    return this.ships.filter((s) => !s.docked && !s.sinking).length;
  }

  getAllShips(): ShipData[] {
    return this.ships;
  }

  clearAllShips() {
    for (const ship of this.ships) {
      ship.entity.dispose();
    }
    this.ships = [];
  }

  update(delta: number, time: number) {
    // Spawn queued ships
    if (this.shipsToSpawn > 0) {
      this.spawnTimer -= delta;
      if (this.spawnTimer <= 0) {
        this.spawnShip();
        this.shipsToSpawn--;
        this.spawnTimer = this.spawnInterval;
      }
    }

    const beamOrigin = this.lighthouseSystem.getBeamOrigin();
    const beamDir = this.lighthouseSystem.getBeamDirection();
    const beamActive = this.lighthouseSystem.isBeamActive();
    const rockPositions = this.envSystem.rockPositions;

    for (let i = this.ships.length - 1; i >= 0; i--) {
      const ship = this.ships[i];
      if (ship.docked) continue;

      const pos = ship.entity.object3D!.position;

      // Handle sinking
      if (ship.sinking) {
        ship.sinkProgress += delta * 0.5;
        pos.y = -ship.sinkProgress * 3;
        ship.entity.object3D!.rotation.z = Math.sin(time * 5) * ship.sinkProgress * 0.5;
        if (ship.sinkProgress >= 1) {
          ship.entity.dispose();
          this.ships.splice(i, 1);
        }
        continue;
      }

      // Check if lit by beam
      if (beamActive) {
        // Project ship position onto beam line
        this.tempVec.copy(pos).sub(beamOrigin);
        const dot = this.tempVec.dot(beamDir);
        if (dot > 0) {
          this.tempVec2.copy(beamDir).multiplyScalar(dot);
          const perpDist = this.tempVec.sub(this.tempVec2).length();
          const beamWidthAtDist = dot * 0.18; // cone angle
          ship.isLit = perpDist < beamWidthAtDist + BEAM_HIT_RADIUS;
        } else {
          ship.isLit = false;
        }
      } else {
        ship.isLit = false;
      }

      // Update lit timer
      if (ship.isLit) {
        ship.litTimer = Math.min(ship.litTimer + delta, 2.0);
      } else {
        ship.litTimer = Math.max(ship.litTimer - delta * 0.5, 0);
      }

      // Navigation
      if (ship.litTimer > 0.3) {
        // Steer toward harbor
        const toHarbor = this.tempVec
          .copy(HARBOR_POS)
          .sub(pos)
          .normalize();
        const targetHeading = Math.atan2(toHarbor.x, toHarbor.z);
        let angleDiff = targetHeading - ship.heading;
        while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;
        while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;
        ship.heading += angleDiff * delta * 2;
      } else {
        // Drift slightly — random wander
        ship.heading += (Math.sin(time + i * 3.7) * 0.2) * delta;
      }

      // Move ship
      const moveSpeed = ship.speed * delta;
      pos.x += Math.sin(ship.heading) * moveSpeed;
      pos.z += Math.cos(ship.heading) * moveSpeed;

      // Bob on waves
      pos.y = Math.sin(time * 1.5 + i * 2) * 0.15;

      // Face heading direction
      ship.entity.object3D!.rotation.y = ship.heading;
      ship.entity.object3D!.rotation.z = Math.sin(time * 2 + i) * 0.05;

      // Pulse navigation lights
      const lightPulse = ship.isLit ? 2.0 : 0.5 + Math.sin(time * 3 + i) * 0.3;
      ship.portLight.intensity = lightPulse;
      ship.starboardLight.intensity = lightPulse;

      // Check harbor dock
      const distToHarbor = pos.distanceTo(HARBOR_POS);
      if (distToHarbor < DOCK_RADIUS) {
        ship.docked = true;
        this.audioSystem?.playDockChime();
        continue;
      }

      // Check rock collisions
      for (const rockPos of rockPositions) {
        const dist = pos.distanceTo(rockPos);
        if (dist < 2.5) {
          ship.sinking = true;
          this.audioSystem?.playCrashSound();
          break;
        }
      }

      // Check out of bounds
      if (pos.length() > SPAWN_DISTANCE + 10) {
        ship.sinking = true;
      }
    }
  }
}

import { createSystem } from '@iwsdk/core';

export class AudioSystem extends createSystem({}) {
  private ctx!: AudioContext;
  private masterGain!: GainNode;
  private volumeOn = true;
  private initialized = false;
  private ambientOsc: OscillatorNode | null = null;
  private ambientGain: GainNode | null = null;

  init() {
    // Defer AudioContext creation until user interaction
    const initAudio = () => {
      if (this.initialized) return;
      this.initialized = true;
      this.ctx = new AudioContext();
      this.masterGain = this.ctx.createGain();
      this.masterGain.gain.value = 0.4;
      this.masterGain.connect(this.ctx.destination);
      this.startAmbient();
      document.removeEventListener('click', initAudio);
      document.removeEventListener('pointerdown', initAudio);
    };
    document.addEventListener('click', initAudio);
    document.addEventListener('pointerdown', initAudio);
  }

  private startAmbient() {
    if (!this.ctx) return;
    // Ocean ambient — low rumble
    this.ambientOsc = this.ctx.createOscillator();
    this.ambientOsc.type = 'sine';
    this.ambientOsc.frequency.value = 40;
    this.ambientGain = this.ctx.createGain();
    this.ambientGain.gain.value = 0.05;
    this.ambientOsc.connect(this.ambientGain);
    this.ambientGain.connect(this.masterGain);
    this.ambientOsc.start();
  }

  toggleVolume() {
    this.volumeOn = !this.volumeOn;
    if (this.masterGain) {
      this.masterGain.gain.value = this.volumeOn ? 0.4 : 0;
    }
  }

  isVolumeOn(): boolean {
    return this.volumeOn;
  }

  playFoghorn() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(80, now);
    osc.frequency.linearRampToValueAtTime(60, now + 2);
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.15, now + 0.3);
    gain.gain.setValueAtTime(0.15, now + 1.5);
    gain.gain.linearRampToValueAtTime(0, now + 2.5);
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start(now);
    osc.stop(now + 2.5);
  }

  playShipBell() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.value = 800;
    gain.gain.setValueAtTime(0.2, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.8);
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start(now);
    osc.stop(now + 0.8);

    // Second ring
    const osc2 = this.ctx.createOscillator();
    const gain2 = this.ctx.createGain();
    osc2.type = 'sine';
    osc2.frequency.value = 1000;
    gain2.gain.setValueAtTime(0.15, now + 0.15);
    gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.7);
    osc2.connect(gain2);
    gain2.connect(this.masterGain);
    osc2.start(now + 0.15);
    osc2.stop(now + 0.7);
  }

  playBeamHum() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.value = 120;
    gain.gain.value = 0.03;
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start(now);
    osc.stop(now + 0.1);
  }

  playDockChime() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const notes = [523, 659, 784]; // C5, E5, G5
    for (let i = 0; i < notes.length; i++) {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sine';
      osc.frequency.value = notes[i];
      const t = now + i * 0.12;
      gain.gain.setValueAtTime(0.2, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.6);
      osc.connect(gain);
      gain.connect(this.masterGain);
      osc.start(t);
      osc.stop(t + 0.6);
    }
  }

  playCrashSound() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    // White noise burst for crash
    const bufferSize = this.ctx.sampleRate * 0.5;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = (Math.random() * 2 - 1) * Math.exp(-i / (bufferSize * 0.2));
    }
    const noise = this.ctx.createBufferSource();
    noise.buffer = buffer;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.3, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.5);
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 600;
    noise.connect(filter);
    filter.connect(gain);
    gain.connect(this.masterGain);
    noise.start(now);
    noise.stop(now + 0.5);

    // Low boom
    const osc = this.ctx.createOscillator();
    const boomGain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(100, now);
    osc.frequency.exponentialRampToValueAtTime(30, now + 0.4);
    boomGain.gain.setValueAtTime(0.3, now);
    boomGain.gain.exponentialRampToValueAtTime(0.001, now + 0.4);
    osc.connect(boomGain);
    boomGain.connect(this.masterGain);
    osc.start(now);
    osc.stop(now + 0.4);
  }

  playWaveComplete() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const notes = [392, 494, 587, 659, 784]; // G4 B4 D5 E5 G5
    for (let i = 0; i < notes.length; i++) {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.value = notes[i];
      const t = now + i * 0.1;
      gain.gain.setValueAtTime(0.2, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
      osc.connect(gain);
      gain.connect(this.masterGain);
      osc.start(t);
      osc.stop(t + 0.5);
    }
  }

  playUIClick() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = 'sine';
    osc.frequency.value = 600;
    gain.gain.setValueAtTime(0.1, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start(now);
    osc.stop(now + 0.1);
  }

  playGameOver() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const notes = [440, 370, 311, 262]; // A4 F#4 Eb4 C4
    for (let i = 0; i < notes.length; i++) {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.value = notes[i];
      const t = now + i * 0.25;
      gain.gain.setValueAtTime(0.12, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
      osc.connect(gain);
      gain.connect(this.masterGain);
      osc.start(t);
      osc.stop(t + 0.5);
    }
  }

  playStormWind() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const bufferSize = this.ctx.sampleRate * 2;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = (Math.random() * 2 - 1) * 0.5;
    }
    const noise = this.ctx.createBufferSource();
    noise.buffer = buffer;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.08, now + 0.5);
    gain.gain.setValueAtTime(0.08, now + 1.5);
    gain.gain.linearRampToValueAtTime(0, now + 2);
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = 400;
    filter.Q.value = 0.5;
    noise.connect(filter);
    filter.connect(gain);
    gain.connect(this.masterGain);
    noise.start(now);
    noise.stop(now + 2);
  }

